mapper.update:
UPDATE group_template
SET status = 1,
    `order` = #{order}
WHERE group_id = #{groupId}
  AND template_id = #{templateId}
  AND status = 0

mapper.delete:
UPDATE group_template
SET status = 0
WHERE id = #{groupTemplateId}

UPDATE group_template
SET status = 0
WHERE group_id = #{groupId}
  AND template_id = #{templateId}
  AND status = 1

mapper.select:
select gt.id, gt.template_id, gt.group_id, t.name, CASE WHEN t.leader_id = 'default' THEN 1 ELSE t.status END as status, t.leader_id, CASE WHEN tp.status = 1 THEN true ELSE false END as pinned, tp.pinned_time from group_template gt join template t on gt.template_id = t.id and (t.status = 1 or (t.leader_id = 'default' and t.status != 2)) left join template_pin tp on gt.id = tp.group_template_id and tp.user_id = #{userId} where gt.group_id in
#{groupId}
and gt.status = 1 order by CASE WHEN tp.status = 1 THEN 0 ELSE 1 END, tp.pinned_time DESC, gt.`order`

select id
from user_template
where user_id = #{userId}
  and leader_id = #{leaderId}
  and status = 1
